import{_ as a,o as l,c as o,j as t}from"./chunks/framework.BdHuibk5.js";const u=JSON.parse('{"title":"生活杂谈","description":"最近有些心浮气躁，也越来越在意时间过得太快。说到底，还是希望生活更有激情，也希望能交到值得做一辈子朋友的人。","frontmatter":{"title":"生活杂谈","date":"2012-11-05 23:08","category":"diary","tags":["生活","朋友"],"slug":"life-chat","layout":"blog-post","description":"最近有些心浮气躁，也越来越在意时间过得太快。说到底，还是希望生活更有激情，也希望能交到值得做一辈子朋友的人。"},"headers":[],"relativePath":"blog/life-chat.md","filePath":"blog/posts/diary/life-chat.md","lastUpdated":1789447662000}'),s={name:"blog/life-chat.md"};function n(r,e,p,i,c,d){return l(),o("div",null,[...e[0]||(e[0]=[t("p",null,"最近比较心浮气躁，静不下心来去思考，去做一些事，持续近一个多月了。希望能出去走走，散散心。又到一年年底，永远都嫌弃时间，嫌他过得太快，原本的紧迫感一扫而空。计划好的一些事也没能去执行，变化总是比计划快，也只能找这么一个破理由来安慰自己。屌丝叫习惯了，真的就成了屌丝，过屌丝的生活。生活还是需要有激情，每天得过得更充实，这是我一直以来所追求，也是一直在做的。每天工作更加投入，更加勤奋。",-1),t("p",null,"有人说，就算再好再铁的哥们，要是三个月甚至更久不联系，那两人之间的关系也会渐渐地淡化，直到失去联系。但是，我不信！我相信的是，真正的哥们，就算一直不联系，但哪天突然接到对方电话短信的时候，也肯定不会找不到话题，更不会感觉到尴尬。但是，最好别尝试这么做。永远不要拿朋友去验证一些不值得验证的玩笑话。",-1),t("p",null,"朋友跟兄弟是有区别的，什么样的才是兄弟？举个例子：你在浙江碰到了困难，必须要你兄弟本人过来帮忙（这里的困难当然不是开玩笑的），而他却并不是在杭州这边，也许是在江苏、北京，甚至于更远，但你一个电话过去，他立马放下手头的事能赶过来，在我眼里，这样的人，才能算得上是兄弟。而这样的人，我用两只手能数得过来，也足够了。",-1),t("p",null,"朋友也分好多种，酒肉朋友、招呼友等等，这样子的，我不喜欢深交。",-1),t("p",null,"有共同的兴趣，共同的爱好，在一起能相互促进、相互鼓励的，我希望能交到更多这样的朋友。讲义气，够仗义，平时虽然大话满天飞，但真正到了关键时刻，还是能挺身而出的，也是值得深交的。",-1),t("p",null,"我希望我能交到更多这样的朋友，可以做一辈子的朋友。",-1)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
